using System.Globalization;using System.Windows;using RefaccionariaDesktop.Models;
namespace RefaccionariaDesktop;
public partial class ProductWindow:Window{
 public Product ProductData{get;private set;}=new();public ProductWindow(){InitializeComponent();}
 public ProductWindow(Product existing):this(){Title="Editar producto";ProductData=existing;CodeBox.Text=existing.Code;NameBox.Text=existing.Name;BrandBox.Text=existing.Brand;PartBox.Text=existing.PartNumber;CostBox.Text=existing.Cost.ToString(CultureInfo.CurrentCulture);PriceBox.Text=existing.Price.ToString(CultureInfo.CurrentCulture);StockBox.Text=existing.Stock.ToString();MinBox.Text=existing.MinStock.ToString();CategoryBox.SelectedIndex=existing.Category=="Motocicletas"?1:0;}
 void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CodeBox.Text)||string.IsNullOrWhiteSpace(NameBox.Text)){MessageBox.Show("Código y descripción son obligatorios.");return;}if(!decimal.TryParse(CostBox.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var cost)||!decimal.TryParse(PriceBox.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var price)||!int.TryParse(StockBox.Text,out var stock)||!int.TryParse(MinBox.Text,out var min)||cost<0||price<0||stock<0||min<0){MessageBox.Show("Revisa costo, precio y existencias.");return;}ProductData=new Product{Id=ProductData.Id,Code=CodeBox.Text.Trim(),Name=NameBox.Text.Trim(),Category=(CategoryBox.SelectedItem as System.Windows.Controls.ComboBoxItem)?.Content?.ToString()??"Agrícolas",Brand=BrandBox.Text.Trim(),PartNumber=PartBox.Text.Trim(),Cost=cost,Price=price,Stock=stock,MinStock=min};DialogResult=true;}
}